import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong association to outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        y0 = feats.x[feats.y == 0, i]
        y1 = feats.x[feats.y == 1, i]
        tstat, _ = stats.ttest_ind(y0, y1)
        effects.append((fid, abs(tstat)))

    # Sort by effect size
    effects.sort(key=lambda x: x[1], reverse=True)

    # Select top candidates
    candidates = [fid for fid, _ in effects[:20]]

    # Check for product terms among highly correlated pairs
    correlations = {}
    for i, fid1 in enumerate(candidates):
        for j, fid2 in enumerate(candidates[i+1:], i+1):
            corr = np.corrcoef(feats.x[:, feats.column(fid1)], 
                              feats.x[:, feats.column(fid2)])[0,1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr

    # Score potential interactions using mutual information
    best_interaction = None
    best_score = 0

    for (fid1, fid2), corr in correlations.items():
        # Create interaction term
        col1 = feats.column(fid1)
        col2 = feats.column(fid2)
        prod = feats.x[:, col1] * feats.x[:, col2]

        # Mutual info with outcome
        mi = mutual_info_classif(prod.reshape(-1, 1), feats.y)[0]
        if mi > best_score:
            best_score = mi
            best_interaction = (fid1, fid2)

    # Return design
    if best_interaction:
        return Design(
            drivers=(best_interaction[0],),
            columns=(best_interaction[0], best_interaction[1]),
            products=(best_interaction,),
            loadings={best_interaction[0]: 1.0, best_interaction[1]: 1.0}
        )
    else:
        return Design(
            drivers=(),
            columns=tuple(candidates[:MAX_DRIVERS]),
            products=(),
            loadings={}
        )

